function islandLife(){state.islandLife??={colonies:[],quests:{},lights:true,fort:null};const a=state.islandLife;a.forts??=[];if(a.fort){const saved=a.forts.find(f=>f.id===a.fort.id);if(saved)a.fort=saved;else a.forts.push(a.fort);}return a}
function expansionEscape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function currentRiverIsland(){return riverAdventure().islands.find(i=>Math.hypot(state.p.x/T-i.x-.5,state.p.y/T-i.y-.5)<=3)}
function foundIslandColony(name){const a=islandLife(),i=currentRiverIsland();if(!i||!i.claimed||state.playerBoat?.aboard||a.colonies.some(c=>c.id===i.id)||state.wood<70||state.stone<15)return false;name=String(name||'Nowa Przystań').trim().slice(0,32)||'Nowa Przystań';const free=[];for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const x=i.x+dx,y=i.y+dy;if(Math.hypot(dx,dy)>2||!dx&&!dy||building(x,y)||foreignBuilding(x,y)||natural(x,y)||terrain(x,y)!=='grass'||Math.floor(state.p.x/T)===x&&Math.floor(state.p.y/T)===y)continue;free.push({x,y})}if(free.length<2)return false;state.wood-=70;state.stone-=15;for(let n=0;n<2;n++)state.buildings.push({...free[n],type:n?'sklad':'dom',colonyId:i.id});a.colonies.push({id:i.id,name,x:i.x,y:i.y});peopleSignature='';syncResidents();save();ui();renderIslandLife(true);say('Powstała osada '+name+'! Dom przyciągnął 3 mieszkańców.');return true}
