function chooseStoneBridge(){setMode('most_staly');stoneBridgeMode=true;$('mode').textContent='Most kamienny · 10 drewna, 30 kamienia / pole';$('islandLifePanel').classList.add('hidden')}
function withStoneBridgeCost(fn){const d=defs.find(d=>d[0]==='most_staly'),wood=d[3],stone=d[4];d[3]=10;d[4]=30;try{return fn()}finally{d[3]=wood;d[4]=stone}}
const islandBuild=build;build=function(x,y){if(mode!=='most_staly'||!stoneBridgeMode){islandBuild(x,y);return}const existing=building(x,y);if(['most','most_staly'].includes(existing?.type)){say('Most kamienny postaw na wolnym odcinku wody.');return}const n=state.buildings.length;withStoneBridgeCost(()=>islandBuild(x,y));const b=building(x,y);if(state.buildings.length>n&&b?.type==='most_staly'){b.stoneBridge=true;b.hp=buildingMaxHp(b);save();ui()}};
