const islandBridge=drawBridge;drawBridge=function(b,x,y){if(!b.stoneBridge){islandBridge(b,x,y);return}ctx.save();ctx.translate(x,y-5);if(bridgeAxis(b)==='vertical')ctx.rotate(Math.PI/2);artRect(-24,-17,48,34,'#aaa99a');for(let row=0;row<4;row++)for(let col=0;col<5;col++)artRect(-24+col*12-(row%2)*6,-16+row*8,11,7,row%2?'#bfc0ac':'#b1b5a3');for(const side of [-21,17]){artRect(-24,side,48,5,'#737f75');for(let j=-24;j<24;j+=12)artRect(j,side-3,9,5,'#d3cfb8')}ctx.restore()};
const lampDefs=[['latarnia','☀','Latarnia',12,5,'Oświetla teren w nocy w promieniu 4 pól.'],['pochodnia','♨','Pochodnia',4,0,'Oświetla teren w nocy w promieniu 2,5 pola.']];for(const d of lampDefs){defs.push(d);const button=document.createElement('button');button.textContent=d[1]+' '+d[2]+' · '+d[3]+' drewna, '+d[4]+' kamienia';button.onclick=()=>setMode(d[0]);$('buildings').append(button)}
const stoneBridgeButton=document.createElement('button');stoneBridgeButton.textContent='🌉 Most kamienny · 10 drewna, 30 kamienia';stoneBridgeButton.onclick=chooseStoneBridge;$('buildings').append(stoneBridgeButton);
function nightStrength(){const p=state.time%240;return p<120?0:Math.sin((p-120)/120*Math.PI)*.48}
const islandStructure=structure;structure=function(b,x,y){if(!['latarnia','pochodnia'].includes(b.type)){islandStructure(b,x,y);return}const lantern=b.type==='latarnia';artRect(x-3,y-(lantern?37:21),6,lantern?46:30,'#655239');if(lantern){artRect(x-8,y-47,16,17,'#4d6257');artRect(x-5,y-44,10,11,'#f2ce80');polygon([[x-11,y-47],[x,y-55],[x+11,y-47]],'#5b7869')}else{ctx.fillStyle='#e8b75c';ctx.beginPath();ctx.ellipse(x,y-24,5,9,0,0,7);ctx.fill();ctx.fillStyle='#ffe3a1';ctx.beginPath();ctx.ellipse(x,y-24,2,5,0,0,7);ctx.fill()}};
const nightMask=document.createElement('canvas'),nightMaskContext=nightMask.getContext('2d');
