const ISLAND_JOBS=[{id:'wood',title:'Drewno na naprawy',key:'wood',cost:20,reward:35},{id:'stone',title:'Kamień dla murarza',key:'stone',cost:15,reward:40},{id:'food',title:'Zapasy dla rodziny',key:'food',cost:10,reward:25},{id:'lights',title:'Jasna osada',reward:45,ready:()=>state.buildings.filter(b=>['latarnia','pochodnia'].includes(b.type)).length>=2},{id:'colony',title:'Nowy dom na wyspie',reward:75,ready:()=>islandLife().colonies.length>0}];
