function finishIslandJob(id){const d=ISLAND_JOBS.find(d=>d.id===id),q=islandLife().quests[id],r=q&&residents.find(r=>r.id===q.owner);if(!d||q?.status!=='active'||!r||Math.hypot(r.x-state.p.x,r.y-state.p.y)>3*T||d.key&&state[d.key]<d.cost||d.ready&&!d.ready())return false;if(d.key)state[d.key]-=d.cost;state.gold+=d.reward;q.status='done';save();ui();renderIslandLife(true);say(r.name+': Dziękuję! Nagroda: '+d.reward+' monet.');return true}
function startPirateFort(){const s=islandLife();if(s.forts.length>=5)return false;const a=riverAdventure(),origin=state.settled?.y||120;let spot=null;for(let k=0;k<N&&!spot;k++){const y=((Math.floor(origin+160+k)-15)%(N-30)+N-30)%(N-30)+15,x=Math.round(river(y));if(safeIsland(x,y))spot={x,y}}if(!spot)return false;const i={...spot,id:s.forts.length?'pirate-fort-'+(s.forts.length+1):'pirate-fort',kind:'fort',name:['Twierdza Czarnej Bandery','Fort Krwawego Żagla','Bastion Morskiego Kruka','Cytadela Sztormu','Twierdza Ostatniej Fali'][s.forts.length],claimed:false};a.islands.push(i);for(let dx=-2;dx<=2;dx++)for(let dy=-2;dy<=2;dy++)if(dx*dx+dy*dy<=7)cut.add(tileKey(i.x+dx,i.y+dy));s.fort={id:i.id,phase:'ready',attempt:0};s.forts.push(s.fort);ensurePirateGarrison();waterRevision++;atlasTerrainSignature='';save();renderIslandLife(true);riverWaypoint(i.id);say('Twierdza oznaczona na mapie. Piraci bronią twierdzy. Zabierz wojsko i wysadź je na wyspie.');return true}
function ensurePirateGarrison(f=islandLife().fort){const i=f&&riverAdventure().islands.find(i=>i.id===f.id);if(!i||!['ready','retry'].includes(f.phase))return false;f.attempt=(f.attempt||0)+1;f.raidId=f.id+'-raid-'+f.attempt;f.phase='battle';if(!state.war.raids.some(r=>r.townId===f.raidId))state.war.raids.push({townId:f.raidId,camp:f.raidId,power:30,hostile:true,progress:0,route:[{x:i.x+.5,y:i.y+.5},{x:i.x+.5,y:i.y+.5}]});save();return true}
