function updateIslandLife(){for(const f of islandLife().forts){ensurePirateGarrison(f);if(f.phase==='battle'){const r=state.war.raids.find(r=>r.townId===f.raidId);if(!r||r.power<=0){f.phase='cleared';if(typeof grantCampGems==='function')grantCampGems('fort:'+f.id);save();say('Piracka załoga pokonana! Podejdź do twierdzy, by ją przejąć.')}}}renderIslandLife()}
