const islandWorld=drawWarWorld;drawWarWorld=function(){islandWorld();for(const c of islandLife().colonies)if(seen.has(tileKey(c.x,c.y))){const x=(c.x+.5)*T,y=(c.y+.5)*T;artRect(x-1,y-42,3,31,'#ddc68e');polygon([[x+2,y-42],[x+22,y-37],[x+2,y-28]],'#7ca087');ctx.font='11px system-ui';artRect(x-42,y-64,ctx.measureText(c.name).width+10,17,'#20392ed9');ctx.fillStyle='#eed9a6';ctx.fillText(c.name,x-37,y-51)}for(const f of islandLife().forts){const i=riverAdventure().islands.find(i=>i.id===f.id);if(i&&seen.has(tileKey(i.x,i.y))){const x=(i.x+.5)*T,y=(i.y+.5)*T;artRect(x-26,y-26,52,38,'#7c8580');for(const dx of [-27,16]){artRect(x+dx,y-50,13,62,'#a6ab9c');for(let k=0;k<3;k++)artRect(x+dx+k*5,y-56,4,8,'#b8baaa')}artRect(x-7,y-10,14,22,'#35473c');artRect(x,y-75,2,40,'#d8c698');polygon([[x+2,y-75],[x+27,y-70],[x+2,y-57]],f.phase==='owned'?'#789c83':'#3e4145');ctx.fillStyle='#eed9a6';ctx.font='11px system-ui';ctx.fillText(f.phase==='owned'?'TWOJA TWIERDZA':'PIRACKA TWIERDZA',x-55,y-83)}}};
const islandPanel=document.createElement('aside');islandPanel.id='islandLifePanel';islandPanel.className='war-panel hidden';islandPanel.innerHTML='<div class="war-title"><h2>Osady, światło i piraci</h2><button id="islandLifeClose">✕</button></div><div id="islandLifeContent"></div>';document.body.append(islandPanel);const islandOpen=document.createElement('button');islandOpen.textContent='🏝 Osady, światło i piraci';islandOpen.onclick=()=>{$('islandLifePanel').classList.remove('hidden');renderIslandLife(true)};$('clockControls').append(islandOpen);$('islandLifeClose').onclick=()=>$('islandLifePanel').classList.add('hidden');
let islandPanelSignature='';function renderIslandLife(force=false){if($('islandLifePanel').classList.contains('hidden'))return;const a=islandLife(),i=currentRiverIsland(),sig=JSON.stringify([a,i?.id,Math.floor(state.time/5),residents.length,Math.floor(state.wood),Math.floor(state.stone),state.gold]);if(!force&&(sig===islandPanelSignature||document.activeElement?.id==='colonyName'))return;islandPanelSignature=sig;const draft=$('colonyName')?.value||'Nowa Przystań';const button=(k,t)=>'<button data-island-life="'+k+'">'+t+'</button>';$('islandLifeContent').innerHTML='<h3>Osada na wyspie</h3><p>Najpierw zbadaj wyspę, wysiądź na ląd i podejdź do jej środka. Koszt: 70 drewna i 15 kamienia. Powstają dom z 3 mieszkańcami i skład. Na wolnych polach buduj miejsca pracy.</p><input id="colonyName" aria-label="Nazwa osady" maxlength="32" placeholder="Nazwa osady" value="'+expansionEscape(draft)+'">'+button('colony','Załóż osadę na tej wyspie')+a.colonies.map(c=>'<p>⚑ '+expansionEscape(c.name)+' · '+c.x+', '+c.y+' · domy: '+state.buildings.filter(b=>b.type==='dom'&&Math.hypot(b.x-c.x,b.y-c.y)<4).length+'</p>').join('')+'<h3>Mosty i oświetlenie</h3><p>Most kamienny: 10 drewna i 30 kamienia za odcinek, 240 PŻ. Cykl dnia i nocy trwa 4 minuty gry. Latarnie i pochodnie rozjaśniają noc.</p>'+button('buildmenu','Otwórz menu budowy — mosty, latarnie i pochodnie')+button('night',a.lights?'Wyłącz przyciemnienie nocy':'Włącz nocne oświetlenie')+'<h3>Zlecenia mieszkańców</h3><p>Przyjmij zlecenie. Aby je oddać, podejdź do zleceniodawcy na 3 pola. Nagroda jest jednorazowa.</p>'+ISLAND_JOBS.map(d=>{const q=a.quests[d.id],r=q&&residents.find(r=>r.id===q.owner),text=d.key?d.cost+' '+({wood:'drewna',stone:'kamienia',food:'żywności'}[d.key]):d.id==='lights'?'Zbuduj 2 źródła światła':'Załóż osadę na wyspie';return '<p><b>'+d.title+'</b> · '+text+' · '+d.reward+' monet'+(r?' · '+expansionEscape(r.name)+' ('+Math.floor(r.x/T)+', '+Math.floor(r.y/T)+')':'')+'</p>'+button((q?'finish:':'accept:')+d.id,q?.status==='done'?'✓ Wykonano':q?'Oddaj zlecenie':'Przyjmij zlecenie')}).join('')+'<h3>Twierdza Czarnej Bandery</h3><p>Piraci są widoczni od odkrycia twierdzy. Wysadź żołnierzy na wyspie i wskaż piratów rozkazem Atakuj lub przyciskiem poniżej. Zalecane co najmniej 4 osoby; możesz atakować mniejszym oddziałem. Pokonaj załogę i podejdź do twierdzy. Nagroda: 250 monet, do 60 drewna (zależnie od miejsca w magazynie) oraz baza do założenia osady.</p><p>Stan: '+({ready:'Przygotuj desant',battle:'Piracka załoga broni twierdzy',cleared:'Załoga pokonana — przejmij bazę',owned:'Twoja baza',retry:'Możesz ponowić szturm'}[a.fort?.phase]||'Wyprawa nie rozpoczęta')+'</p>'+button('fort','Odkryj kolejną twierdzę · '+a.forts.length+'/5')+a.forts.map(f=>button('choosefort:'+f.id,expansionEscape(riverAdventure().islands.find(i=>i.id===f.id)?.name||'Twierdza')+(f.phase==='owned'?' · ✓ zdobyta':f===a.fort?' · wybrana':''))).join('')+button('locate','Pokaż kierunek do twierdzy')+button('attack','Atakuj piracką załogę')+button('capture','Przejmij twierdzę')}
$('islandLifeContent').onclick=e=>{const b=e.target.closest('[data-island-life]');if(!b)return;const [k,id]=b.dataset.islandLife.split(':');let ok=true;switch(k){case 'colony':ok=foundIslandColony($('colonyName').value);break;case 'buildmenu':renderConstruction();constructionPanel.classList.remove('hidden');$('islandLifePanel').classList.add('hidden');break;case 'bridge':chooseStoneBridge();break;case 'lamp':setMode('latarnia');$('islandLifePanel').classList.add('hidden');break;case 'torch':setMode('pochodnia');$('islandLifePanel').classList.add('hidden');break;case 'night':islandLife().lights=!islandLife().lights;save();break;case 'accept':ok=acceptIslandJob(id);break;case 'finish':ok=finishIslandJob(id);break;case 'fort':ok=startPirateFort();break;case 'locate':if(islandLife().fort)riverWaypoint(islandLife().fort.id);else ok=false;break;case 'choosefort':islandLife().fort=islandLife().forts.find(f=>f.id===id)||islandLife().fort;save();break;case 'attack':ok=attackPirateFort();break;case 'capture':ok=capturePirateFort();break}if(ok===false)say('Sprawdź warunki opisane w panelu oraz odległość i zasoby.');renderIslandLife(true)};window.addEventListener('keydown',e=>{if(e.key==='Escape')$('islandLifePanel').classList.add('hidden')});islandLife();for(const fort of islandLife().forts)ensurePirateGarrison(fort);
